//! Shared domain and event types. This file is the contract between the Rust core,
//! the adapters, and the Svelte UI (TypeScript bindings are generated by ts-rs into
//! `src/lib/gen/` when `cargo test -p codly-core` runs).
//!
//! Rules:
//! - Every type that crosses the IPC boundary derives `TS` + `#[ts(export)]`.
//! - Enums serialize as snake_case strings; tagged unions use `type` (events) or `kind`.
//! - IDs are UUIDv7 strings (time-sortable). Timestamps are unix epoch milliseconds.

use serde::{Deserialize, Serialize};
use serde_json::Value;
use ts_rs::TS;

pub type Id = String;

pub fn new_id() -> Id {
    uuid::Uuid::now_v7().to_string()
}

pub fn default_lead_thread() -> String {
    "lead".into()
}

/// Request threads: "lead" (the first) and "lead:<id>" (parallel requests, each with its own
/// Lead session). 1:1 agent threads are "agent:<id>".
pub fn is_lead_thread(thread: &str) -> bool {
    thread == "lead" || thread.starts_with("lead:")
}

pub fn now_ms() -> i64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_millis() as i64)
        .unwrap_or(0)
}

// ───────────────────────────── providers & CLIs ─────────────────────────────

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(export)]
pub enum Provider {
    Claude,
    Codex,
    Gemini,
    Opencode,
    Cursor,
    Copilot,
}

impl Provider {
    pub const ALL: [Provider; 6] = [
        Provider::Claude,
        Provider::Codex,
        Provider::Gemini,
        Provider::Opencode,
        Provider::Cursor,
        Provider::Copilot,
    ];
    pub fn as_str(self) -> &'static str {
        match self {
            Provider::Claude => "claude",
            Provider::Codex => "codex",
            Provider::Gemini => "gemini",
            Provider::Opencode => "opencode",
            Provider::Cursor => "cursor",
            Provider::Copilot => "copilot",
        }
    }
    pub fn label(self) -> &'static str {
        match self {
            Provider::Claude => "Claude Code",
            Provider::Codex => "Codex",
            Provider::Gemini => "Gemini CLI",
            Provider::Opencode => "OpenCode",
            Provider::Cursor => "Cursor",
            Provider::Copilot => "Copilot",
        }
    }
}

/// Who pays for an agent's tokens. Shown as a badge on every agent.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(export)]
pub enum Billing {
    Subscription,
    ApiKey,
    ThirdParty,
    Unknown,
}

/// Result of detecting one agent CLI on this machine (env.rs).
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct CliInfo {
    pub provider: Provider,
    /// Absolute path of the resolved binary, if found.
    pub path: Option<String>,
    pub version: Option<String>,
    /// None = unknown (no cheap status command for this CLI).
    pub logged_in: Option<bool>,
    pub billing: Billing,
    /// Plan / account label, e.g. "team", "plus", "api key".
    pub plan: Option<String>,
    /// Human-readable problem, e.g. "not signed in: run `claude` once".
    pub problem: Option<String>,
    /// Integration path Codly uses, e.g. "stream-json", "app-server", "acp".
    pub transport: String,
}

// ───────────────────────────── accounts ─────────────────────────────

/// A sign-in the user wants Codly to know about: one value of the provider's account
/// variable (`CLAUDE_CONFIG_DIR`, `CODEX_HOME`, `GEMINI_CLI_HOME`). Stored in `Settings`.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct AccountConfig {
    pub provider: Provider,
    /// The variable's value; None = the variable unset (the CLI's default sign-in).
    pub home: Option<String>,
    /// The user's name for it ("work", "perso"). None = derived from the home.
    #[serde(default)]
    pub label: Option<String>,
    pub enabled: bool,
}

/// How work spreads over several accounts of one CLI.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(export)]
pub enum AccountStrategy {
    /// The account with the most quota left gets the next task.
    #[default]
    Spread,
    /// Accounts in your order; the next one only takes over near the first one's limit.
    InOrder,
}

/// One usage window of an account, as its agents last reported it.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct UsageWindow {
    /// "five_hour", "seven_day", …
    pub window: String,
    pub used_fraction: f64,
    pub resets_at: Option<i64>,
    /// "allowed" | "allowed_warning" | "rejected" …
    pub status: Option<String>,
    pub seen_at: i64,
}

/// A detected sign-in of an agent CLI, with its known quota. Providers without an account
/// variable (OpenCode, Cursor, Copilot) have exactly one, mirroring their `CliInfo`.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct AccountInfo {
    /// Stable id: "claude" for the default sign-in, "claude:/Users/me/.claude-work" otherwise.
    pub id: String,
    pub provider: Provider,
    pub home: Option<String>,
    /// The user's label, else one derived from the home ("default", "work").
    pub label: String,
    /// Codly may run agents on it.
    pub enabled: bool,
    /// The sign-in your login shell uses (what the CLI does in your terminal).
    pub primary: bool,
    /// Listed in your settings (otherwise found on disk).
    pub configured: bool,
    pub logged_in: Option<bool>,
    pub billing: Billing,
    pub plan: Option<String>,
    /// Who is signed in, when the CLI says (Claude: "you@x.com · Org").
    pub identity: Option<String>,
    pub problem: Option<String>,
    /// The shell command that signs this account in.
    pub login_command: Option<String>,
    pub limits: Vec<UsageWindow>,
}

