// ───────────────────────────── artifacts & repo map ─────────────────────────────

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(export)]
pub enum ArtifactKind {
    Image,
    Svg,
    Html,
    Markdown,
    Pdf,
    Csv,
}

impl ArtifactKind {
    /// Artifact kind for a file name, by extension (None = not an artifact).
    pub fn for_path(path: &str) -> Option<(ArtifactKind, &'static str)> {
        let ext = path.rsplit_once('.').map(|(_, e)| e.to_ascii_lowercase())?;
        Some(match ext.as_str() {
            "png" => (ArtifactKind::Image, "image/png"),
            "jpg" | "jpeg" => (ArtifactKind::Image, "image/jpeg"),
            "gif" => (ArtifactKind::Image, "image/gif"),
            "webp" => (ArtifactKind::Image, "image/webp"),
            "svg" => (ArtifactKind::Svg, "image/svg+xml"),
            "html" | "htm" => (ArtifactKind::Html, "text/html"),
            "md" | "markdown" => (ArtifactKind::Markdown, "text/markdown"),
            "pdf" => (ArtifactKind::Pdf, "application/pdf"),
            "csv" => (ArtifactKind::Csv, "text/csv"),
            _ => return None,
        })
    }
}

/// A file an agent produced that is worth looking at, not just diffing: an image (incl.
